<?php require 'config.php'; if(!empty($_SESSION['user'])){header('Location:dashboard.php');exit;} $err='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$pdo->prepare("SELECT * FROM users WHERE username=?");$s->execute([trim($_POST['username']??'')]);$u=$s->fetch();
if(!$u||!password_verify($_POST['password']??'',$u['password']))$err='Incorrect username or password.';
elseif($u['status']!=='approved')$err=$u['status']==='pending'?'Your account is waiting for admin approval.':'Your account has not been approved.';
else{session_regenerate_id(true);$_SESSION['user']=['id'=>$u['id'],'username'=>$u['username'],'role'=>$u['role']];header('Location:dashboard.php');exit;}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sign In | Inventory System</title><link rel="stylesheet" href="assets/style.css"></head><body class="auth"><main class="card"><div class="mark">IS</div><small>INVENTORY MANAGEMENT</small><h1>Welcome back</h1><p>Sign in to manage your inventory.</p><?php if($err):?><div class="alert"><?=$err?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Username</label><input name="username" required><label>Password</label><input type="password" name="password" required><button>Sign In</button></form><p class="center">Don't have an account? <a href="register.php">Create account</a></p></main></body></html>